from target import merge_free_slots

def test_already_sorted():
    assert merge_free_slots([[1, 2], [2, 3]]) == [(1, 3)]

def test_empty_input():
    assert merge_free_slots([]) == []

def test_unsorted():
    assert merge_free_slots([[7, 9], [1, 3], [2, 5]]) == [(1, 5), (7, 9)]
